#!/usr/bin/env node
/* Prove the phone codec produces the same bytes as k1lib.
 *
 *     node tools/phone/check_frames.js /tmp/vectors.json
 *
 * The vectors are generated by the Python side (`protocol.packet`, the same
 * function the laptop sends with), so this is a cross-implementation check,
 * not a snapshot of the JS agreeing with itself. Also exercises the stream
 * reassembler: two frames in one notification, and one frame split at every
 * possible boundary.
 */
"use strict";

var fs = require("fs");
var F = require("./frames.js");

var file = process.argv[2];
if (!file) {
  console.error("usage: node check_frames.js <vectors.json>");
  process.exit(2);
}

var vectors = JSON.parse(fs.readFileSync(file, "utf8"));
var failures = 0;

function check(label, ok, extra) {
  if (!ok) failures += 1;
  console.log((ok ? "PASS" : "FAIL") + "  " + label + (extra && !ok ? "  " + extra : ""));
}

vectors.forEach(function (v) {
  var frame = F.encode(v.type, v.payload);
  check("encode " + v.name, F.hex(frame) === v.hex, "got " + F.hex(frame) + " want " + v.hex);
  var parsed = F.parse(frame);
  check("parse " + v.name, parsed && parsed.valid && parsed.type === v.code,
        parsed ? "valid=" + parsed.valid + " type=" + parsed.type : "null");
  if (parsed) {
    // The byte comparison above is the proof. Text only makes sense for the
    // textual payloads; a bool/byte vector (autoStand) has no text to check.
    if (v.payload === null || typeof v.payload === "string") {
      var text = v.payload === null ? "" : F.text(parsed.data);
      check("payload " + v.name, text === (v.payload === null ? "" : v.payload),
            JSON.stringify(text));
    }
  }
});

console.log("");
var a = F.encode("action", "ProAction/Say Hello");
var b = F.encode("audio", "02/401");

var joined = new Uint8Array(a.length + b.length);
joined.set(a, 0);
joined.set(b, a.length);
var two = F.splitStream({}, joined);
check("two frames in one chunk", two.length === 2 &&
      F.hex(two[0]) === F.hex(a) && F.hex(two[1]) === F.hex(b),
      two.length + " frames");

var state = { remainder: new Uint8Array(0) };
var got = [];
for (var i = 0; i < a.length; i++) {
  got = got.concat(F.splitStream(state, a.subarray(i, i + 1)));
}
check("one frame split byte by byte", got.length === 1 && F.hex(got[0]) === F.hex(a),
      got.length + " frames");

var junk = new Uint8Array(3 + a.length);
junk.set([0x00, 0x12, 0x34], 0);
junk.set(a, 3);
var afterJunk = F.splitStream({}, junk);
check("junk before the header is skipped",
      afterJunk.length === 1 && F.hex(afterJunk[0]) === F.hex(a),
      afterJunk.length + " frames");

var corrupt = F.encode("action", "ProAction/Say Hello");
corrupt[corrupt.length - 1] ^= 0xff;
var bad = F.parse(corrupt);
check("bad checksum is detected", bad !== null && bad.valid === false);

console.log("\n" + (failures ? failures + " FAILURE(S)" : "ALL PASS"));
process.exit(failures ? 1 : 0);
